// Package native is the registry of compiled ("native") packages that the
// tree-walking interpreter can call into. Tables are generated by
// wy/internal/extract (see tree/stdlib) and can also be built by hosts
// for their own packages with `wy extract`.
package native

import (
	"go/constant"
	"reflect"
	"sync"
)

// Package describes the exported API of a compiled package.
type Package struct {
	Path, Name string
	Funcs      map[string]reflect.Value // function values
	Vars       map[string]reflect.Value // pointers to variables
	Types      map[string]reflect.Type  // named types (and aliases)
	Consts     map[string]Const
	// Wrappers maps an interface type name to a generated struct type that
	// implements it by forwarding calls to a Caller (its first field).
	Wrappers map[string]reflect.Type
}

// Const is an exported constant. Type is nil for untyped constants, whose
// kind is then given by Untyped ("bool", "int", "rune", "float", "complex",
// "string").
type Const struct {
	Value   constant.Value
	Type    reflect.Type
	Untyped string
}

// Caller is implemented by interpreter values; wrappers forward their
// method calls through it. Arguments and results are native values.
type Caller interface {
	Call(method string, args []any) []any
}

var (
	mu       sync.RWMutex
	registry = map[string]*Package{}
	wrappers = map[reflect.Type]bool{}
)

// Register adds or replaces a package.
func Register(p *Package) {
	mu.Lock()
	defer mu.Unlock()
	registry[p.Path] = p
	for _, w := range p.Wrappers {
		wrappers[w] = true
	}
}

// Lookup returns the registered package with the given import path.
func Lookup(path string) *Package {
	mu.RLock()
	defer mu.RUnlock()
	return registry[path]
}

// Paths lists registered packages.
func Paths() []string {
	mu.RLock()
	defer mu.RUnlock()
	out := make([]string, 0, len(registry))
	for p := range registry {
		out = append(out, p)
	}
	return out
}

// IsWrapper reports whether t is a generated wrapper type.
func IsWrapper(t reflect.Type) bool {
	mu.RLock()
	defer mu.RUnlock()
	return wrappers[t]
}

// RegisterWrapper marks t as a wrapper type (used for combo wrappers).
func RegisterWrapper(t reflect.Type) {
	mu.Lock()
	defer mu.Unlock()
	wrappers[t] = true
}

// As converts a wrapper call result to T, mapping nil to T's zero value.
func As[T any](v any) T {
	t, _ := v.(T)
	return t
}

// Combo is a wrapper implementing a combination of commonly probed
// optional methods (String, Error, Unwrap, Is, As, Format, ...).
type Combo struct {
	Type    reflect.Type
	Methods []string // method keys, see ComboMethods
}

//go:generate go run gen_combos.go

// Combos lists all combo wrappers; filled by zcombos.go.
var Combos []Combo
